import { SiteSettings } from "@/lib/theme-types";
import Link from "next/link";

export default function Footer({ settings }: { settings: SiteSettings }) {
  return (
    <footer className="w-full border-t border-black/5 bg-background text-text">
      <div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-8 md:flex-row md:items-center md:justify-between">
        <p className="text-sm text-secondary">{settings.footerText}</p>

        <nav className="flex flex-wrap items-center gap-4">
          {settings.footerNavLinks.map((link) => (
            <Link
              key={link.url + link.label}
              href={link.url}
              target={link.openInNewTab ? "_blank" : undefined}
              rel={link.openInNewTab ? "noopener noreferrer" : undefined}
              className="text-sm text-secondary hover:text-primary transition-colors"
            >
              {link.label}
            </Link>
          ))}
        </nav>

        {!!settings.socialLinks?.length && (
          <div className="flex items-center gap-4">
            {settings.socialLinks.map((link) => (
              <a
                key={link.url + link.label}
                href={link.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-secondary hover:text-primary transition-colors"
              >
                {link.label}
              </a>
            ))}
          </div>
        )}
      </div>
    </footer>
  );
}
